package hu.keepimproving.android;
import org.junit.*;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import android.content.*;
import org.json.*;
import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class PhoneCompanionTest {
    @org.robolectric.annotation.Implements(value=Vault.class,isInAndroidSdk=false)
    public static class UsbVault { @org.robolectric.annotation.Implementation protected static String read(Context context){return CODE;} }
    static final String CODE="a1".repeat(16),DEVICE="b".repeat(32),HASH="0".repeat(64);
    static JSONObject companion() throws Exception {return new JSONObject().put("format","KeepImproving.companion.v1").put("settings",new JSONObject().put("check_updates",true)).put("focus",new JSONObject().put("work",25).put("short_break",5).put("long_break",15).put("rounds",4).put("tracking",true)).put("budgets",new JSONArray().put(new JSONObject().put("id","shared-games").put("name","Shared game budget").put("scope","shared").put("seconds",3600).put("enabled",true).put("usage_limit",true).put("reset_minute",0).put("days",new JSONArray("[0,1,2,3,4,5,6]")).put("members",new JSONArray("[{\"kind\":\"category\",\"value\":\"games\"}]")))).put("notifications",new JSONArray()).put("games",new JSONArray("[{\"id\":\"steam:42\",\"name\":\"Example game\",\"source\":\"Steam\"}]")).put("events",new JSONArray()).put("hashes",new JSONObject().put("setting:check_updates",HASH).put("budget:shared-games",HASH).put("focus:",HASH)).put("empty_hash",HASH);}
    static JSONObject snapshot(PhoneStore s) throws Exception{return s.snapshot(CODE).put("device",DEVICE).put("name","Asztali PC").put("companion",companion()).put("focus_rounds",new JSONArray().put(new JSONArray().put(java.time.LocalDate.now().toString()).put(3)));}
    static JSONArray envelope(JSONObject snapshot) throws Exception{String revision=Long.toString(snapshot.getLong("revision"));return new JSONArray().put(new JSONObject().put("device",DEVICE).put("revision",revision).put("payload",SyncCrypto.seal(snapshot.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),CODE,DEVICE,revision)));}
    @Test public void importedRoundsNeverBecomeLocalAndRepeatedImportReplaces()throws Exception{try(PhoneStore s=new PhoneStore(RuntimeEnvironment.getApplication())){String day=java.time.LocalDate.now().toString();s.getWritableDatabase().execSQL("INSERT INTO focus_rounds VALUES (?,?,?,?)",new Object[]{day,"local",1,System.currentTimeMillis()});JSONObject snapshot=snapshot(s);JSONArray incoming=envelope(snapshot);s.accept(incoming,CODE);s.accept(incoming,CODE);assertEquals(4,PhoneCompanion.rounds(s,day));assertEquals(1,s.rounds(day));assertEquals(1,s.snapshot(CODE).getJSONArray("focus_rounds").getJSONArray(0).getInt(1));snapshot.put("revision",snapshot.getLong("revision")+1).put("focus_rounds",new JSONArray().put(new JSONArray().put(day).put(5)));s.accept(envelope(snapshot),CODE);assertEquals(6,PhoneCompanion.rounds(s,day));PhoneCompanion.clear(s);assertEquals(1,PhoneCompanion.rounds(s,day));}}
    @Test public void targetedQueueKeepsPendingAndAcceptsOnlyTargetAcknowledgement()throws Exception{try(PhoneStore s=new PhoneStore(RuntimeEnvironment.getApplication())){JSONObject d=companion().put("device",DEVICE);PhoneCompanion.queue(s,d,"setting","check_updates",false);assertThrows(IllegalStateException.class,()->PhoneCompanion.queue(s,d,"setting","check_updates",true));JSONObject command=s.snapshot(CODE).getJSONArray("remote_commands").getJSONObject(0);assertEquals(DEVICE,command.getString("target"));JSONObject snapshot=snapshot(s);JSONObject result=new JSONObject().put("id",command.getString("id")).put("origin",s.device()).put("status","applied");snapshot.getJSONObject("companion").put("command_results",new JSONArray().put(result));s.accept(envelope(snapshot),CODE);assertEquals(0,PhoneCompanion.commands(s).length());try(var c=s.getReadableDatabase().rawQuery("SELECT status FROM commands",null)){assertTrue(c.moveToFirst());assertEquals("applied",c.getString(0));}}}
    @Test public void pcClockAndForwardedEventShareOneDurableReceipt()throws Exception{Context c=RuntimeEnvironment.getApplication();Shadows.shadowOf((android.app.Application)c).grantPermissions(android.Manifest.permission.POST_NOTIFICATIONS);try(PhoneStore s=new PhoneStore(c)){long now=System.currentTimeMillis();String day=java.time.LocalDate.now().toString();int minute=java.time.LocalTime.now().getHour()*60+java.time.LocalTime.now().getMinute();JSONObject snap=snapshot(s),d=snap.getJSONObject("companion");JSONObject r=new JSONObject().put("id","r").put("title","Break").put("text","Stretch").put("enabled",true).put("trigger","time").put("minute",minute).put("action",new JSONObject().put("kind","none"));d.getJSONArray("notifications").put(r);d.getJSONArray("events").put(new JSONObject(r.toString()).put("id","event").put("rule_id","r").put("day",day).put("at",now));s.accept(envelope(snap),CODE);s.getWritableDatabase().execSQL("UPDATE companions SET first_seen=?",new Object[]{now-120000});s.put("companion_revision",Long.toString(s.number("companion_revision",0)+1));}PhoneRuntime.refresh(c,false);PhoneRuntime.refresh(c,false);try(PhoneStore s=new PhoneStore(c);var r=s.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM notices WHERE id LIKE 'pc:%'",null)){r.moveToFirst();assertEquals(1,r.getInt(0));}}
    @Test public void invalidFocusHistoryRejectsTheWholeSnapshot()throws Exception{try(PhoneStore s=new PhoneStore(RuntimeEnvironment.getApplication())){JSONObject snap=snapshot(s).put("focus_rounds",new JSONArray().put(new JSONArray().put("2026-11-04").put(-1)));assertThrows(IllegalArgumentException.class,()->s.accept(envelope(snap),CODE));assertEquals(0,s.known().length());}}
    @Test @Config(shadows=UsbVault.class) public void encryptedUsbImportReturnsOnlyLocalHistoryAndKeepsCloudGuard()throws Exception{Context c=RuntimeEnvironment.getApplication();JSONObject body;try(PhoneStore s=new PhoneStore(c)){s.put("sync_after","9999999999999");body=new JSONObject().put("format",SyncProtocol.CLOUD).put("need_upload",false).put("snapshots",envelope(snapshot(s)));}java.io.File input=new java.io.File(c.getExternalFilesDir("usb"),"request.json");java.nio.file.Files.write(input.toPath(),body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));Intent intent=new Intent(c,MainActivity.class).setAction(UsbTransfer.ACTION);try(var controller=Robolectric.buildActivity(MainActivity.class,intent).setup()){CollectionJob.LOAD.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);MainActivity a=controller.get();java.io.File file=new java.io.File(a.getExternalFilesDir("usb"),"response.json");assertTrue(file.exists());JSONObject reply=new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),java.nio.charset.StandardCharsets.UTF_8));JSONObject phone=SyncProtocol.decode(reply,CODE);assertNotEquals(DEVICE,phone.getString("device"));assertEquals(0,phone.getJSONArray("focus_rounds").length());try(PhoneStore s=new PhoneStore(c)){assertEquals(3,PhoneCompanion.rounds(s,java.time.LocalDate.now().toString()));assertEquals("9999999999999",s.get("sync_after",""));}Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();CollectionJob.LOAD.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}}
    @Test public void unusedActivitiesAndApplicationAliasesShareOneCatalogEntry()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();JSONObject d=companion().put("device",DEVICE).put("activities",new JSONArray("[{\"kind\":\"app\",\"key\":\"tool.exe\",\"name\":\"Tool\"},{\"kind\":\"site\",\"key\":\"unused.example\",\"name\":\"Unused\"}]"));JSONObject snapshot=new JSONObject().put("device",DEVICE).put("rows",new JSONArray()).put("activity",new JSONArray().put(new JSONArray().put("2026-11-04").put("app").put("c:\\old\\tool.exe").put("Tool").put(30)).put(new JSONArray().put("2026-11-04").put("app").put("c:\\new\\tool.exe").put("Tool").put(60)));a.devices.add(snapshot);var items=RemoteScreens.items(a,d);assertEquals(3,items.size());assertEquals(1,items.stream().filter(i->i.key().equals("tool.exe")).count());assertTrue(items.stream().anyMatch(i->i.key().equals("unused.example")));}
    @Test public void migrationFromV2PreservesRulesAndFocusHistory()throws Exception{Context c=RuntimeEnvironment.getApplication();String device;try(PhoneStore s=new PhoneStore(c)){device=s.device();s.saveRule("budget",PhoneRules.budget().put("name","Keep").put("category","games"));s.getWritableDatabase().execSQL("INSERT INTO focus_rounds VALUES ('2026-11-04','round',1,1)");s.getWritableDatabase().setVersion(2);}try(PhoneStore s=new PhoneStore(c)){assertEquals(6,s.getWritableDatabase().getVersion());assertEquals(device,s.device());assertEquals(1,s.rules("budget").length());assertEquals(1,s.rounds("2026-11-04"));}}
}
